const out = [];
let first = true;
for (const it of items) {
  for (const p of (it.json.projects || [])) {
    out.push({ json: {
      project_id: p.project_id,
      project_name: p.name,
      base_lang: (p.base_language_iso || 'en').toLowerCase(),
      qa_type: 'double_space',
      qa_label: 'DoubleSpace'
    }});
    if (first) {
      out.push({ json: {
        project_id: p.project_id,
        project_name: p.name,
        base_lang: 'en',
        qa_type: '__control_invalid__',
        qa_label: '__CONTROL__'
      }});
      first = false;
    }
  }
}
return out;

const PER = 500;
const MAX_PAGES = 20;
const reqs = $('Build Count Requests').all();
const res = $input.all();
const out = [];
const failed = [];
const capped = [];
let controlStatus = null;
let scanned = 0;
let flaggedTotal = 0;

for (let i = 0; i < res.length; i++) {
  const pi = res[i].pairedItem;
  let idx = i;
  if (pi && typeof pi === 'object' && typeof pi.item === 'number') { idx = pi.item; }
  else if (typeof pi === 'number') { idx = pi; }
  const metaItem = reqs[idx] || reqs[i];
  if (!metaItem) { continue; }
  const meta = metaItem.json;

  const r = res[i].json || {};
  const hdr = r.headers || {};
  if (meta.qa_label === '__CONTROL__') { controlStatus = r.statusCode; continue; }

  scanned++;
  const raw = hdr['x-pagination-total-count'];
  let total = null;
  if (r.statusCode === 200 && raw !== undefined && raw !== null) {
    const n = parseInt(raw, 10);
    if (!isNaN(n)) { total = n; }
  }
  if (total === null) { failed.push(meta.project_name); continue; }
  if (total === 0) { continue; }
  flaggedTotal += total;

  let pages = Math.ceil(total / PER);
  if (pages > MAX_PAGES) { pages = MAX_PAGES; capped.push(meta.project_name); }
  for (let p = 1; p <= pages; p++) {
    out.push({ json: {
      project_id: meta.project_id,
      project_name: meta.project_name,
      base_lang: meta.base_lang,
      page: p
    }});
  }
}

for (const o of out) {
  o.json.scanned = scanned;
  o.json.failed = failed;
  o.json.capped = capped;
  o.json.control_status = controlStatus;
  o.json.flagged_total = flaggedTotal;
}
if (out.length === 0) {
  out.push({ json: { project_id: null, project_name: null, base_lang: 'en', page: 0, scanned: scanned, failed: failed, capped: capped, control_status: controlStatus, flagged_total: 0 } });
}
return out;

function classify(s) {
  if (typeof s !== 'string' || s === '') { return 'skip_empty'; }
  if (!/ {2,}/.test(s)) { return 'skip_no_double'; }
  if (/\u00A0|\u202F|\u2009/.test(s)) { return 'review_nbsp'; }
  if (s.indexOf('<') >= 0 || s.indexOf('&nbsp;') >= 0) { return 'review_html'; }
  if (/[\n\r\t]/.test(s)) { return 'review_real_newline'; }
  if (/\\[nrt]/.test(s)) { return 'review_escaped_newline'; }
  if (/^\s|\s$/.test(s)) { return 'review_edge_space'; }
  if (s.indexOf('$t(') >= 0 || s.indexOf('[%s:') >= 0 || s.indexOf('{') >= 0) { return 'review_interpolation'; }
  return 'safe';
}
function keyName(k) {
  const n = k.key_name;
  if (typeof n === 'string') { return n; }
  if (n && typeof n === 'object') { return n.web || n.other || n.ios || n.android || String(k.key_id); }
  return String(k.key_id);
}
function isPseudo(iso) {
  const s = (iso || '').toLowerCase();
  return s === 'pst' || s.indexOf('pseudo') >= 0;
}

const reqs = $('Build Page Requests').all();
const res = $input.all();
const meta0 = (reqs[0] || { json: {} }).json;
const seenKey = {};
const readFail = [];

const cats = {};
const byProject = {};
const samples = {};
const safeRows = [];
let affected = 0;
let keysExamined = 0;

function bump(obj, k) { obj[k] = (obj[k] || 0) + 1; }

for (let i = 0; i < res.length; i++) {
  const pi = res[i].pairedItem;
  let idx = i;
  if (pi && typeof pi === 'object' && typeof pi.item === 'number') { idx = pi.item; }
  else if (typeof pi === 'number') { idx = pi; }
  const metaItem = reqs[idx] || reqs[i];
  if (!metaItem) { continue; }
  const meta = metaItem.json;
  if (!meta.project_id) { continue; }

  const r = res[i].json || {};
  if (r.statusCode !== 200) { readFail.push(meta.project_name + ' p' + meta.page); continue; }
  const keys = (r.body && r.body.keys) ? r.body.keys : [];

  for (const k of keys) {
    if (k.is_archived) { continue; }
    const dk = meta.project_id + '#' + k.key_id;
    if (seenKey[dk]) { continue; }
    seenKey[dk] = 1;
    keysExamined++;

    if (!byProject[meta.project_name]) { byProject[meta.project_name] = { safe: 0, safe_unreviewed_target: 0, review: 0, source: 0 }; }

    for (const tr of (k.translations || [])) {
      const v = tr.translation;
      if (typeof v !== 'string') { continue; }
      const iso = (tr.language_iso || '').toLowerCase();
      if (isPseudo(iso)) { continue; }
      const cat = classify(v);
      if (cat === 'skip_empty' || cat === 'skip_no_double') { continue; }
      affected++;
      const isSource = iso === meta.base_lang;
      bump(cats, cat);
      if (isSource) { byProject[meta.project_name].source++; }
      if (cat === 'safe') {
        byProject[meta.project_name].safe++;
        if (!isSource && !tr.is_reviewed) {
          byProject[meta.project_name].safe_unreviewed_target++;
          safeRows.push({
            project: meta.project_name,
            project_id: meta.project_id,
            translation_id: tr.translation_id,
            key: keyName(k),
            key_id: k.key_id,
            lang: iso,
            before: v.length > 240 ? v.slice(0, 240) + '…' : v,
            after: (v.length > 240 ? v.slice(0, 240) + '…' : v).replace(/ {2,}/g, ' ')
          });
        }
      } else {
        byProject[meta.project_name].review++;
      }
      if (!samples[cat]) { samples[cat] = []; }
      if (samples[cat].length < 4) {
        samples[cat].push({
          project: meta.project_name, lang: iso, key: keyName(k),
          text: JSON.stringify(v.length > 160 ? v.slice(0, 160) + '…' : v)
        });
      }
    }
  }
}

const safeTotal = cats.safe || 0;
const pct = affected > 0 ? Math.round((safeTotal / affected) * 100) : 0;

return [{ json: {
  projects_scanned: meta0.scanned || 0,
  flagged_keys_total: meta0.flagged_total || 0,
  keys_examined: keysExamined,
  affected_translations: affected,
  safe_total: safeTotal,
  safe_pct: pct,
  safe_unreviewed_target: safeRows.length,
  categories: cats,
  by_project: byProject,
  samples: samples,
  failed: (meta0.failed || []).concat(readFail),
  capped: meta0.capped || [],
  control_status: meta0.control_status,
  safe_rows: safeRows
}}];
